use regex::Regex;
use serde::Serialize;
use serde_yaml;
use std::fs;

#[derive(Debug, Serialize)]
struct OscDoc {
    osc_address: String,
    params: Vec<OscArgOrParam>,
    arguments: Vec<OscArgOrParam>,
    access_tags: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    comments: Vec<String>,
}

#[derive(Debug, Serialize)]
struct OscArgOrParam {
    name: String,
    r#type: String,
    description: String,
}

const YAML_HEADER: &str = r#"
# This file is autogenerated. Do not edit directly.
# Generated by reaper-arpad/tools/oscdoc
#
# This file contains OSC documentation extracted from the source code defining the OSC routes exposed by reaper-arpad.
#
# Each entry defines an Open Sound Control (OSC) route and specifies the OSC address, parameters, arguments, access flags, and any additional comments.
#
# Generally, each OSC route accepts or transmits a single argument, although this is not strictly enforced.
#
# Routes may also include parameters encoded within the address itself, denoted by `{}`-delimited placeholders. These parameters are defined in a `params` section.
# Callers should replace these placeholders with appropriate values when constructing OSC messages.
# The following parameter types are supported:
# - int: 32-bit integer
# - string: UTF-8 string
#
# Routes may be used in 3 ways, each of which is indicated by a corresponding access tag:
# 1. readable: The route transmits data FROM the application. The client can listen for messages on this route.
#   When Reaper sends these messages, their placeholders will be populated.

# 2. writeable: The route accepts data TO the application. The client can send messages to this route.
#   It is the client's responsibility to populate the placeholders with appropriate values.
#   Whatever argument the client passes will be the new value set within Reaper.
#   NOTE: writeable does NOT imply readable.

# 3. queryable: The route supports querying, which prompts the application to send the current value back to the client along this route.
#   To query a route, append `?` to the end of the address. Any arguments are discarded when querying. Reaper will respond on the readable version of this route (WITHOUT appending `?`).
#   Parameters are still required in the address when querying (whenever the route includes placeholders).
#   NOTE: queryable implies readable.
"#;

/// Tool to extract OSC documentation from Rust source code and output as YAML.
///
/// Osc documentation is formatted as formatted doc comments preceding
/// the function definition, starting with a line containing `@osc-doc`.
///
/// Osc routes are composed of an address and zero or more arguments. Arguments may be of the
/// following types:
/// - int: 32-bit integer
/// - float: 32-bit float
/// - string: UTF-8 string
/// - bool: boolean
///
/// Practically, each route typically accepts or receives a single argument, although this is not strictly
/// enforced.
///
/// Incorrect argument types are ignored.
///
/// Minimal example:
/// /// @osc-doc
/// /// This function does something important.
/// /// OSC Address: /example/address
/// /// - arg (int): The first argument.
///
/// Frequently, OSC routes encode information within the route itself. These parameters are defiend
/// in a `params` section. Parameters are typed and then encoded into the route in place of
/// `{}`-delimited placeholders.
///
/// Parameters may be of the following types:
/// - int: 32-bit integer
/// - string: UTF-8 string
///
/// In addition, routes are marked with one or more of the following accessibility tags:
/// - @readable: The route transmits data FROM the application. The client can listen for messages on this route.
/// - @writeable: The route accepts data TO the application. The client can send messages to this route.
///   @writeable does NOT imply @readable.
/// - @queryable: The route supports querying, which prompts the application to send the current value back to the client along this route.
///   To query a route, append `?` to the end of the address. Any arguments are discarded when querying. The application responds to the route WITHOUT appending `?`.
///   Parameters are still required in the address when querying (whenever the route includes placeholders).
///   @queryable implies @readable.
///
/// Routes no tags have no effect.
///
/// Example:
/// /// @osc-doc
/// /// @writeable
/// /// @readable
/// /// @queryable
/// /// Sets the value of a track FX parameter.
/// /// OSC Address: /track/{track_guid}/fx/{fx_index}/param/{param_index}/value
/// /// - params:
/// ///    - track_guid (string): The GUID of the track.
/// ///    - fx_index (int): The index of the FX on the track.
/// ///    - param_index (int): The index of the parameter on the FX.
/// /// - args:
/// ///    - value (float): The value of the parameter
///
/// Example output (YAML):
/// - osc_address: /track/{track_guid}/fx/{fx_index}/param/{param_index}/value
///   comments:
///   - Sets the value of a track FX parameter.
///   params:
///   - name: track_guid
///     type: string
///     description: unique identifier for the track
///   - name: fx_index
///     type: int
///     description: index of the FX on the track
///   - name: param_index
///     type: int
///     description: index of the parameter on the FX
///   args:
///   - name: value
///     type: float
///     description: The value of the parameter
///   access:
///   - readable
///   - writeable
///   - queryable
fn main() {
    let src = fs::read_to_string("src/osc_routes.rs").expect("No src/lib.rs found");
    let re = Regex::new(r"(?s)/// ?@osc-doc\n(.*?)(?:fn (\w+)[^\n]*\{)").unwrap();

    let mut docs = Vec::new();

    let osc_re = Regex::new(r"^.*///\s*OSC Address:\s*(.*)$").unwrap();
    let arg_re = Regex::new(r"^.*///\s*-\s*(\w+)\s*\((\w+)\):\s*(.*)$").unwrap();

    for cap in re.captures_iter(&src) {
        let docblock = &cap[1];

        let mut comments = Vec::new();
        let mut osc_address = None;
        let mut arguments = Vec::new();

        let mut in_osc_section = false;

        let mut direction = None;

        for line in docblock.lines() {
            if line.contains("@readonly") {
                direction = Some("readonly".to_string());
                continue;
            }
            if line.contains("@writeonly") {
                direction = Some("writeonly".to_string());
                continue;
            }

            if osc_re.is_match(line) {
                osc_address = Some(osc_re.captures(line).unwrap()[1].to_string());
                in_osc_section = true;
                continue;
            }
            if in_osc_section {
                if let Some(arg_cap) = arg_re.captures(line) {
                    arguments.push(OscArgOrParam {
                        name: arg_cap[1].to_string(),
                        r#type: arg_cap[2].to_string(),
                        description: arg_cap[3].to_string(),
                    });
                }
            } else {
                // Collect as comment (strip leading /// and whitespace)
                comments.push(line.trim_start_matches("///").trim().to_string());
            }
        }

        docs.push(OscDoc {
            osc_address: osc_address.unwrap_or_default(),
            arguments,
            direction,
            comments: comments.into_iter().filter(|c| !c.is_empty()).collect(),
        });
    }

    // Output header
    fs::write("osc_docs.yaml", YAML_HEADER).unwrap();

    // Output yaml
    let yaml = serde_yaml::to_string(&docs).unwrap();
    fs::write("osc_docs.yaml", yaml).unwrap();
}
